import{_ as o,o as r,c as t,a6 as n}from"./chunks/framework.Ci0opSHZ.js";const m=JSON.parse('{"title":"Tensor Operations","description":"","frontmatter":{},"headers":[],"relativePath":"libraries/tensor.md","filePath":"libraries/tensor.md","lastUpdated":null}'),a={name:"libraries/tensor.md"};function s(d,e,c,i,p,l){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="Tensor-Operations" tabindex="-1">Tensor Operations <a class="header-anchor" href="#Tensor-Operations" aria-label="Permalink to &quot;Tensor Operations {#Tensor-Operations}&quot;">​</a></h1><p><code>AMDGPU.jl</code> now provides wrappers for the <a href="https://rocm.docs.amd.com/projects/hipTensor/en/latest/index.html" target="_blank" rel="noreferrer"><code>hipTensor</code></a> library, which can be used to perform operations on high-dimensional arrays. However, there are some caveats:</p><ul><li><p><code>hipTensor</code> isn&#39;t supported on every AMD GPU. You can find the list of supported GPUs <a href="https://rocm.docs.amd.com/projects/hipTensor/en/latest/api-reference/api-reference.html#supported-gpu-architectures" target="_blank" rel="noreferrer">at the <code>hipTensor</code> documentation</a>.</p></li><li><p>for <a href="https://rocm.docs.amd.com/projects/hipTensor/en/latest/api-reference/api-reference.html#hiptensorcreateelementwisetrinary" target="_blank" rel="noreferrer"><code>hiptensorCreateElementwiseTrinary</code></a>, <code>hipTENSOR</code> 2.2 has the two binary operators the wrong way round: it applies the operator passed as <code>opABC</code> to <code>A</code> and <code>B</code>, and the one passed as <code>opAB</code> to that intermediate result and <code>C</code>. This is currently handled by our wrapper.</p></li><li><p>Unlike NVIDIA&#39;s <code>cuTENSOR</code>, <code>hipTENSOR</code> wants a <em>complex</em> compute descriptor for complex operands: pairing e.g. <code>ComplexF32</code> tensors with <code>HIPTENSOR_COMPUTE_DESC_32F</code> makes <code>hiptensorCreatePlan</code> fail with <code>HIPTENSOR_STATUS_EXECUTION_FAILED</code></p></li><li><p>from <code>hipTENSOR</code> 2.4 on (the version in the ROCm 10.0 bundles, for instance), the contraction kernels no longer use the mode labels to work out how their operands line up: they read every descriptor positionally, and only compute the right result when <code>A</code> is indexed by its free modes followed by the contracted ones, <code>B</code> likewise, and <code>C</code> and <code>D</code> by <code>A</code>&#39;s free modes followed by <code>B</code>&#39;s, with every operand packed column-major. Any other layout is <em>silently</em> miscomputed — <code>hiptensorContract</code> reports success and writes a plausible but wrong result — so <code>plan_contraction</code> rejects it with an <code>ArgumentError</code>. Permute the operands with <code>permutedims</code> first. <code>hipTENSOR</code> 2.2 handled arbitrary mode orders, and is left alone</p></li><li><p><code>hipTENSOR</code> 2.2 accepts <code>HIPTENSOR_OP_CONJ</code> on a contraction&#39;s inputs and then silently ignores it, computing the unconjugated product; 2.4 rejects it instead, failing <code>hiptensorCreatePlan</code> with <code>HIPTENSOR_STATUS_EXECUTION_FAILED</code></p></li></ul>',3)])])}const u=o(a,[["render",s]]);export{m as __pageData,u as default};
